def sqrt_root(n):
    if n < 0:
        return None
    if n == 0 or n == 1:
        return n

    # Binary search for the square root
    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2
        square = mid * mid
        if square == n:
            return mid
        elif square < n:
            left = mid + 1
        else:
            right = mid - 1
    return None
```

