def extract_values(s):
    # Remove the outermost quotes and split by comma
    inside_quotes = s.strip()[1:-1]  # Remove the first and last quotes
    values = []
    current = ""
    for char in inside_quotes:
        if char == '"':
            if current:
                values.append(current)
                current = ""
        else:
            current += char
    return values
```

