def remove_words(string_list, chars_or_words):
    result = []
    for item in string_list:
        cleaned_item = item
        for char_or_word in chars_or_words:
            if char_or_word in cleaned_item:
                cleaned_item = cleaned_item.replace(char_or_word, '')
        result.append(cleaned_item)
    return result
```

